mapper.sql:
a.project_id = #{projectId} and a.app_id = #{appId}
and a.object_type = #{objectType} and a.object_id = #{objectId}
and (a.parent_id is null or a.parent_id = 0)

mapper.select:
select  from rdm_event_handler where event = #{event} and (parent_id is null or parent_id = 0)
and project_id = #{projectId}
and app_id = #{appId} order by sort, id

mapper.update:
update rdm_event_handler set parent_id = #{parentId}, name = #{name}, sort = #{sort},
  config = #{configStr, typeHandler=neatlogic.framework.dao.plugin.CompressHandler}, is_active = #{isActive}
where id = #{id} and project_id = #{projectId} and app_id = #{appId}

update rdm_event_audit set end_time = #{endTime}, status = #{status},
  error = #{error, typeHandler=neatlogic.framework.dao.plugin.CompressHandler},
  result = #{resultStr, typeHandler=neatlogic.framework.dao.plugin.CompressHandler}
where id = #{id}
